def create_page(connection_id, parent, title=None, properties=None, icon=None, cover=None, children=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.utcnow()

    def _now():
        return _utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _extract_title(notion_page_obj):
        try:
            props = notion_page_obj.get("properties") if isinstance(notion_page_obj, dict) else None
            if isinstance(props, dict):
                for _, p in props.items():
                    if isinstance(p, dict) and p.get("type") == "title":
                        arr = p.get("title")
                        if isinstance(arr, list):
                            txt = "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in arr])
                            return txt or None
        except Exception:
            return None
        return None

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "create_page",
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # ---- Validate inputs ----
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if not isinstance(parent, dict):
        return _err("VALIDATION_ERROR", "parent must be an object", field="parent")
    ptype = parent.get("type")
    if ptype not in ("page_id", "database_id", "workspace"):
        return _err("VALIDATION_ERROR", "parent.type must be one of page_id, database_id, workspace", field="parent.type")
    # Relax: if missing notion_id for page/database, allow if it can be inferred from configured todos DB parent page
    pnotion = parent.get("notion_id")
    if ptype in ("page_id", "database_id") and (pnotion is not None and not isinstance(pnotion, str)):
        return _err("VALIDATION_ERROR", "parent.notion_id must be a string when provided", field="parent.notion_id")
    if title is not None and not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string when provided", field="title")
    if properties is not None and not isinstance(properties, dict):
        return _err("VALIDATION_ERROR", "properties must be an object when provided", field="properties")
    if icon is not None and not isinstance(icon, dict):
        return _err("VALIDATION_ERROR", "icon must be an object when provided", field="icon")
    if cover is not None and not isinstance(cover, dict):
        return _err("VALIDATION_ERROR", "cover must be an object when provided", field="cover")
    if children is not None:
        if not isinstance(children, list):
            return _err("VALIDATION_ERROR", "children must be an array when provided", field="children")
        for i, ch in enumerate(children[:2000]):
            if not isinstance(ch, dict):
                return _err("VALIDATION_ERROR", "children items must be objects", field=f"children[{i}]")

    # ---- Resolve active connection (must be exactly one active in store; but allow targeting specific id) ----
    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "connection is not active", connection_id=connection_id, status=conn.get("status"))

    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    # infer missing parent.notion_id for page_id only: use configured todos DB's parent page if available
    if ptype == "page_id" and (not pnotion):
        dbs = _load("notion_databases.json")
        if not isinstance(dbs, list):
            dbs = []
        cfg_db_id = conn.get("configured_todos_database_id")
        inferred = None
        if isinstance(cfg_db_id, str) and cfg_db_id:
            for d in dbs:
                if isinstance(d, dict) and d.get("connection_id") == connection_id and d.get("notion_database_id") == cfg_db_id:
                    inferred = d.get("parent_page_notion_id")
                    break
        if inferred:
            pnotion = inferred
        else:
            return _err("VALIDATION_ERROR", "parent.notion_id is required when parent.type is page_id unless it can be inferred from configured todos database", field="parent.notion_id")
    if ptype == "database_id" and not pnotion:
        return _err("VALIDATION_ERROR", "parent.notion_id is required when parent.type is database_id", field="parent.notion_id")

    # ---- Prepare Notion request ----
    notion_parent = {"type": ptype}
    if ptype == "page_id":
        notion_parent["page_id"] = pnotion
    elif ptype == "database_id":
        notion_parent["database_id"] = pnotion
    else:
        notion_parent["workspace"] = True

    req_props = {}
    if isinstance(properties, dict):
        req_props.update(properties)

    # If title provided and no obvious title property, include a best-effort "Name" title property (common pattern).
    if isinstance(title, str) and title.strip():
        # Only add if not already given some title-like property payload
        has_title_payload = False
        for v in req_props.values():
            if isinstance(v, dict) and ("title" in v or v.get("type") == "title"):
                has_title_payload = True
                break
        if not has_title_payload:
            req_props.setdefault("Name", {"title": [{"type": "text", "text": {"content": title.strip()}}]})

    payload = {"parent": notion_parent}
    if req_props:
        payload["properties"] = req_props
    if isinstance(icon, dict) and icon:
        payload["icon"] = icon
    if isinstance(cover, dict) and cover:
        payload["cover"] = cover
    if isinstance(children, list) and children:
        payload["children"] = children

    url = notion_base.rstrip("/") + "/v1/pages"
    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            body = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = ""
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)
    duration_ms = int((time.time() - start) * 1000)

    _log(connection_id, "POST", "/v1/pages", payload, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error creating page", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    if not isinstance(resp_obj, dict) or not resp_obj.get("id"):
        return _err("CONFLICT", "Notion returned an unexpected response for create page", notion_status=status)

    notion_page_id = resp_obj.get("id")
    ts = _now()

    pages = _load("notion_pages.json")
    if not isinstance(pages, list):
        pages = []

    existing_idx = None
    for i, row in enumerate(pages):
        if isinstance(row, dict) and row.get("connection_id") == connection_id and row.get("notion_page_id") == notion_page_id:
            existing_idx = i
            break

    parent_notion_id = None if ptype == "workspace" else pnotion
    notion_db_id = pnotion if ptype == "database_id" else None

    if existing_idx is None:
        new_row = {
            "id": _gen_ulid("npg"),
            "connection_id": connection_id,
            "notion_page_id": notion_page_id,
            "parent_type": ptype,
            "parent_notion_id": parent_notion_id,
            "notion_database_id": notion_db_id,
            "title": _extract_title(resp_obj) or (title.strip() if isinstance(title, str) and title.strip() else None),
            "icon": resp_obj.get("icon") if isinstance(resp_obj.get("icon"), (dict, type(None))) else None,
            "cover": resp_obj.get("cover") if isinstance(resp_obj.get("cover"), (dict, type(None))) else None,
            "archived": False,
            "status": "active",
            "raw_notion": resp_obj,
            "last_synced_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        pages.append(new_row)
        saved_row = new_row
    else:
        row = pages[existing_idx]
        row["parent_type"] = ptype
        row["parent_notion_id"] = parent_notion_id
        row["notion_database_id"] = notion_db_id
        row["status"] = "active"
        row["archived"] = False
        row["raw_notion"] = resp_obj
        row["last_synced_at"] = ts
        row["title"] = _extract_title(resp_obj) or row.get("title") or (title.strip() if isinstance(title, str) and title.strip() else None)
        row["icon"] = resp_obj.get("icon") if isinstance(resp_obj.get("icon"), (dict, type(None))) else row.get("icon")
        row["cover"] = resp_obj.get("cover") if isinstance(resp_obj.get("cover"), (dict, type(None))) else row.get("cover")
        row["updated_at"] = ts
        saved_row = row

    _save("notion_pages.json", pages)

    return {"page": saved_row}

def get_page(connection_id, notion_page_id, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(notion_page_id, str) or not notion_page_id.strip():
        return _err("VALIDATION_ERROR", "notion_page_id is required.")

    conns = _load("notion_connections.json")
    pages = _load("notion_pages.json")
    logs = _load("notion_request_logs.json")

    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.")

    page = next((p for p in pages if p.get("connection_id") == connection_id and p.get("notion_page_id") == notion_page_id), None)
    if page and page.get("status") == "deleted":
        return _err("NOT_FOUND", "Page not found.")

    # Read-through cache: refresh if raw missing or stale (>60s)
    def _parse_ts(ts):
        if not ts or not isinstance(ts, str):
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    stale = True
    if page and page.get("raw_notion") is not None:
        last = _parse_ts(page.get("last_synced_at"))
        if last:
            age = (datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - last).total_seconds()
            stale = age > 60
        else:
            stale = True

    # If not in local store, simulate Notion NOT_FOUND
    if page is None:
        # must log the Notion call attempt too
        duration_ms = max(0, int((time.time() - t0) * 1000))
        log_id = "nrl_" + uuid.uuid4().hex
        logs.append({
            "id": log_id,
            "connection_id": connection_id,
            "tool_name": "get_page",
            "notion_method": "GET",
            "notion_path": f"/v1/pages/{notion_page_id}",
            "request_body": None,
            "response_status": 404,
            "response_body": {"object": "error", "status": 404, "message": "Not found"},
            "duration_ms": duration_ms,
            "error_code": "object_not_found",
            "error_message": "Page not found",
            "created_at": now,
            "updated_at": now,
        })
        _save("notion_request_logs.json", logs)
        return _err("NOT_FOUND", "Page not found or not accessible.")

    if stale:
        # simulate a Notion GET and update cache
        raw = page.get("raw_notion") if isinstance(page.get("raw_notion"), dict) else {}
        raw = {**raw}
        raw.setdefault("object", "page")
        raw["id"] = notion_page_id
        raw["archived"] = bool(page.get("archived"))
        raw["last_edited_time"] = now

        duration_ms = max(0, int((time.time() - t0) * 1000))
        def _truncate(obj, limit=8000):
            try:
                s = json.dumps(obj, ensure_ascii=False)
            except Exception:
                return None
            if len(s) > limit:
                s = s[:limit] + "…"
            try:
                return json.loads(s) if s and s[0] in "{[" else {"truncated": s}
            except Exception:
                return {"truncated": s}

        logs.append({
            "id": "nrl_" + uuid.uuid4().hex,
            "connection_id": connection_id,
            "tool_name": "get_page",
            "notion_method": "GET",
            "notion_path": f"/v1/pages/{notion_page_id}",
            "request_body": None,
            "response_status": 200,
            "response_body": _truncate(raw),
            "duration_ms": duration_ms,
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        })

        page["raw_notion"] = raw
        page["last_synced_at"] = now
        page["updated_at"] = now
        _save("notion_pages.json", pages)
        _save("notion_request_logs.json", logs)

    return {"page": page}

def update_page(connection_id, notion_page_id, properties=None, archived=None, icon=None, cover=None, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not isinstance(notion_page_id, str) or not notion_page_id.strip():
        return _err("VALIDATION_ERROR", "notion_page_id is required.")
    if properties is not None and not isinstance(properties, dict):
        return _err("VALIDATION_ERROR", "properties must be an object.")
    if archived is not None and not isinstance(archived, bool):
        return _err("VALIDATION_ERROR", "archived must be a boolean.")
    if icon is not None and not isinstance(icon, dict):
        return _err("VALIDATION_ERROR", "icon must be an object.")
    if cover is not None and not isinstance(cover, dict):
        return _err("VALIDATION_ERROR", "cover must be an object.")
    if properties is None and archived is None and icon is None and cover is None:
        return _err("VALIDATION_ERROR", "At least one of properties, archived, icon, or cover must be provided.")

    conns = _load("notion_connections.json")
    pages = _load("notion_pages.json")
    logs = _load("notion_request_logs.json")

    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.")

    page = next((p for p in pages if p.get("connection_id") == connection_id and p.get("notion_page_id") == notion_page_id), None)
    if not page or page.get("status") == "deleted":
        return _err("NOT_FOUND", "Page not found.")
    if page.get("status") in ("archived", "deleted"):
        return _err("INVALID_TRANSITION", "Cannot update a page that is archived or deleted.")

    # simulate Notion PATCH
    notion_method = "PATCH"
    notion_path = f"/v1/pages/{notion_page_id}"
    req_body = {}
    if properties is not None:
        req_body["properties"] = properties
    if archived is not None:
        req_body["archived"] = archived
    if icon is not None:
        req_body["icon"] = icon
    if cover is not None:
        req_body["cover"] = cover

    raw = page.get("raw_notion") if isinstance(page.get("raw_notion"), dict) else {"object": "page", "id": notion_page_id}
    raw = {**raw}
    raw["id"] = notion_page_id
    if properties is not None:
        raw["properties"] = properties
    if archived is not None:
        raw["archived"] = archived
    if icon is not None:
        raw["icon"] = icon
    if cover is not None:
        raw["cover"] = cover
    raw["last_edited_time"] = now

    # update mirror fields
    if archived is not None:
        if archived is True:
            # Do not allow direct archiving transition here if you want strict separation; but vendor tool allows it.
            # Enforce lifecycle transition: active -> archived allowed
            page["status"] = "archived"
            page["archived"] = True
        else:
            # unarchive
            page["status"] = "active"
            page["archived"] = False

    if icon is not None:
        page["icon"] = icon
    if cover is not None:
        page["cover"] = cover

    # best-effort title derivation
    derived_title = None
    if isinstance(properties, dict):
        t = properties.get("Name") or properties.get("Title") or properties.get("__server_title")
        if isinstance(t, dict):
            if "title" in t and isinstance(t["title"], str):
                derived_title = t["title"]
            elif "title" in t and isinstance(t["title"], list) and t["title"]:
                # Notion style: list of rich text objects
                first = t["title"][0]
                if isinstance(first, dict):
                    plain = first.get("plain_text") or (first.get("text") or {}).get("content")
                    if isinstance(plain, str):
                        derived_title = plain
    if derived_title is not None:
        page["title"] = derived_title

    page["raw_notion"] = raw
    page["last_synced_at"] = now
    page["updated_at"] = now

    duration_ms = max(0, int((time.time() - t0) * 1000))
    def _truncate(obj, limit=8000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return None
        if len(s) > limit:
            s = s[:limit] + "…"
        try:
            return json.loads(s) if s and s[0] in "{[" else {"truncated": s}
        except Exception:
            return {"truncated": s}

    logs.append({
        "id": "nrl_" + uuid.uuid4().hex,
        "connection_id": connection_id,
        "tool_name": "update_page",
        "notion_method": notion_method,
        "notion_path": notion_path,
        "request_body": _truncate(req_body),
        "response_status": 200,
        "response_body": _truncate(raw),
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    })

    _save("notion_pages.json", pages)
    _save("notion_request_logs.json", logs)
    return {"page": page}

def archive_page(connection_id, notion_page_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
