        next_cursor = None
    else:
        # simulate an empty paginated property if cursors provided; otherwise null value
        property_item = {
            "object": "property_item",
            "id": notion_property_id,
            "type": "unknown",
            "unknown": None,
        }
        has_more = False
        next_cursor = None

    # Persist refreshed value/last_synced_at when we have a prop_row; if not, do not fabricate property rows.
    if prop_row:
        prop_row["last_synced_at"] = now
        prop_row["updated_at"] = now
