        _save("notion_page_properties.json", props)

    # Log outbound call (must happen for every tool invocation that calls Notion; this tool does)
    # Path matches Notion API: GET /v1/pages/{page_id}/properties/{property_id}
    path = f"/v1/pages/{notion_page_id}/properties/{notion_property_id}"
    req_body = None
    dur = int(max(0, (time.time() - t0) * 1000))
    resp_body = {"property_item": property_item, "has_more": has_more, "next_cursor": next_cursor}
    _log(logs, connection_id, "GET", path, req_body, 200, resp_body, dur)
    _save("notion_request_logs.json", logs)

    return {"property_item": property_item, "has_more": has_more, "next_cursor": next_cursor}

