    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    # Build derived properties (best-effort, schema-aware when possible)
    schema = db_row.get("schema") if isinstance(db_row, dict) else None
    schema_props = schema if isinstance(schema, dict) else {}
    # find candidate property names by type
    title_prop_name = None
    select_prop_name = None
    status_prop_name = None
    date_prop_name = None
    multi_select_prop_name = None
    people_prop_name = None
    url_prop_name = None
    checkbox_prop_name = None
    rich_text_prop_name = None

    for pname, pdef in schema_props.items():
        if not isinstance(pname, str) or not isinstance(pdef, dict):
            continue
        ptype = pdef.get("type")
        if ptype == "title" and title_prop_name is None:
            title_prop_name = pname
        elif ptype == "select" and select_prop_name is None:
            select_prop_name = pname
        elif ptype == "status" and status_prop_name is None:
            status_prop_name = pname
        elif ptype == "date" and date_prop_name is None:
            date_prop_name = pname
        elif ptype == "multi_select" and multi_select_prop_name is None:
            multi_select_prop_name = pname
        elif ptype == "people" and people_prop_name is None:
            people_prop_name = pname
        elif ptype == "url" and url_prop_name is None:
            url_prop_name = pname
        elif ptype == "checkbox" and checkbox_prop_name is None:
            checkbox_prop_name = pname
        elif ptype == "rich_text" and rich_text_prop_name is None:
            rich_text_prop_name = pname

    if title_prop_name is None:
        title_prop_name = "Name"

    derived = {
        title_prop_name: {"title": [{"type": "text", "text": {"content": title.strip()}}]},
    }
    if description and rich_text_prop_name:
        derived[rich_text_prop_name] = {"rich_text": [{"type": "text", "text": {"content": description}}]}
    if due_date and date_prop_name:
        derived[date_prop_name] = {"date": {"start": due_date}}
    if completed is not None:
        # prefer checkbox if present, else status/select when present
        if checkbox_prop_name:
            derived[checkbox_prop_name] = {"checkbox": bool(completed)}
        elif status_prop_name:
            derived[status_prop_name] = {"status": {"name": "Done" if completed else "Todo"}}
        elif select_prop_name:
            derived[select_prop_name] = {"select": {"name": "Done" if completed else "Todo"}}
    if priority:
        if status_prop_name:
            derived[status_prop_name] = {"status": {"name": priority}}
        elif select_prop_name:
            derived[select_prop_name] = {"select": {"name": priority}}
    if tags and multi_select_prop_name:
        derived[multi_select_prop_name] = {"multi_select": [{"name": t} for t in tags]}
    if assignees and people_prop_name:
        derived[people_prop_name] = {"people": [{"id": a} for a in assignees]}
    if url and url_prop_name:
        derived[url_prop_name] = {"url": url}

    final_props = dict(derived)
    if isinstance(properties, dict) and properties:
        # merge/override
        for k, v in properties.items():
            final_props[k] = v

    payload = {"parent": {"database_id": db_id}, "properties": final_props}
    if isinstance(content_blocks, list) and content_blocks:
        payload["children"] = content_blocks

    url_ep = notion_base.rstrip("/") + "/v1/pages"
    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_ep, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            body = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = ""
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

    duration_ms = int((time.time() - start) * 1000)
    _log(connection_id, "POST", "/v1/pages", payload, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error creating todo page", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    if not isinstance(resp_obj, dict) or not resp_obj.get("id"):
        return _err("CONFLICT", "Notion returned an unexpected response for add_todo", notion_status=status)

    notion_page_id = resp_obj.get("id")
    ts = _now()

    # Upsert notion_pages
    pages = _load("notion_pages.json")
    if not isinstance(pages, list):
        pages = []
    page_idx = None
    for i, row in enumerate(pages):
        if isinstance(row, dict) and row.get("connection_id") == connection_id and row.get("notion_page_id") == notion_page_id:
            page_idx = i
            break

    def _extract_title_from_resp(o):
        # For database row pages, title is in properties title type; try reuse
        try:
            props = o.get("properties") if isinstance(o, dict) else None
            if isinstance(props, dict):
                for _, p in props.items():
                    if isinstance(p, dict) and p.get("type") == "title":
                        arr = p.get("title")
                        if isinstance(arr, list):
                            txt = "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in arr])
                            return txt or None
        except Exception:
            return None
        return None

    saved_page = None
    if page_idx is None:
        new_row = {
            "id": _gen_ulid("npg"),
            "connection_id": connection_id,
            "notion_page_id": notion_page_id,
            "parent_type": "database_id",
            "parent_notion_id": db_id,
            "notion_database_id": db_id,
            "title": _extract_title_from_resp(resp_obj) or title.strip(),
            "icon": resp_obj.get("icon") if isinstance(resp_obj.get("icon"), (dict, type(None))) else None,
            "cover": resp_obj.get("cover") if isinstance(resp_obj.get("cover"), (dict, type(None))) else None,
            "archived": False,
            "status": "active",
            "raw_notion": resp_obj,
            "last_synced_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        pages.append(new_row)
        saved_page = new_row
    else:
        row = pages[page_idx]
        row["parent_type"] = "database_id"
        row["parent_notion_id"] = db_id
        row["notion_database_id"] = db_id
        row["archived"] = False
        row["status"] = "active"
        row["raw_notion"] = resp_obj
        row["last_synced_at"] = ts
        row["title"] = _extract_title_from_resp(resp_obj) or row.get("title") or title.strip()
        row["updated_at"] = ts
        saved_page = row

    _save("notion_pages.json", pages)

    # Persist relevant properties into notion_page_properties for caching/search support
    props_store = _load("notion_page_properties.json")
    if not isinstance(props_store, list):
        props_store = []

    # Need local page id
    local_page_id = saved_page.get("id")

    def _upsert_prop(notion_property_id, property_name, property_type, value, notion_property_item_id=None):
        nonlocal props_store
        if not local_page_id:
            return
        idx = None
        for i, r in enumerate(props_store):
            if (
                isinstance(r, dict)
                and r.get("connection_id") == connection_id
                and r.get("page_id") == local_page_id
                and r.get("notion_property_id") == notion_property_id
            ):
                idx = i
                break
        if idx is None:
            props_store.append(
                {
                    "id": _gen_ulid("npp"),
                    "connection_id": connection_id,
                    "page_id": local_page_id,
                    "notion_property_id": notion_property_id,
                    "property_name": property_name,
                    "property_type": property_type,
                    "value": value,
                    "notion_property_item_id": notion_property_item_id,
                    "last_synced_at": ts,
                    "created_at": ts,
                    "updated_at": ts,
                }
            )
        else:
            r = props_store[idx]
            r["property_name"] = property_name
            r["property_type"] = property_type
            r["value"] = value
            if notion_property_item_id is not None:
                r["notion_property_item_id"] = notion_property_item_id
            r["last_synced_at"] = ts
            r["updated_at"] = ts

    notion_props = resp_obj.get("properties") if isinstance(resp_obj, dict) else None
    if isinstance(notion_props, dict):
        for prop_name, prop in notion_props.items():
            if not isinstance(prop, dict):
                continue
            ptype = prop.get("type")
            notion_pid = prop.get("id") or prop_name
            # Only store a subset commonly used for todos
            if ptype == "title":
                arr = prop.get("title")
                val = None
                if isinstance(arr, list):
                    val = "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in arr]) or None
                _upsert_prop(notion_pid, prop_name, "title", val)
            elif ptype == "rich_text" and description is not None:
                arr = prop.get("rich_text")
                val = None
                if isinstance(arr, list):
                    val = "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in arr]) or None
                _upsert_prop(notion_pid, prop_name, "rich_text", val)
            elif ptype == "date" and due_date is not None:
                _upsert_prop(notion_pid, prop_name, "date", prop.get("date"))
            elif ptype in ("select", "status") and (priority is not None or completed is not None):
                _upsert_prop(notion_pid, prop_name, ptype, prop.get(ptype))
            elif ptype == "multi_select" and tags is not None:
                _upsert_prop(notion_pid, prop_name, "multi_select", prop.get("multi_select"))
            elif ptype == "people" and assignees is not None:
                _upsert_prop(notion_pid, prop_name, "people", prop.get("people"))
            elif ptype == "checkbox" and completed is not None:
                _upsert_prop(notion_pid, prop_name, "checkbox", prop.get("checkbox"))
            elif ptype == "url" and url is not None:
                _upsert_prop(notion_pid, prop_name, "url", prop.get("url"))

    _save("notion_page_properties.json", props_store)

    return {"page": saved_page}

def search_todos(connection_id, todos_database_id=None, query=None, filter=None, sorts=None, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "search_todos",
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if todos_database_id is not None and not isinstance(todos_database_id, str):
        return _err("VALIDATION_ERROR", "todos_database_id must be a string when provided", field="todos_database_id")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string when provided", field="query")
    if filter is not None and not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object when provided", field="filter")
    if sorts is not None:
        if not isinstance(sorts, list):
            return _err("VALIDATION_ERROR", "sorts must be an array when provided", field="sorts")
        for i, s in enumerate(sorts[:100]):
            if not isinstance(s, dict):
                return _err("VALIDATION_ERROR", "sorts items must be objects", field=f"sorts[{i}]")
    if start_cursor is not None and not isinstance(start_cursor, str):
        return _err("VALIDATION_ERROR", "start_cursor must be a string when provided", field="start_cursor")
    if page_size is None:
        page_size = 20
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100", field="page_size")

    # Resolve connection
    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "connection is not active", connection_id=connection_id, status=conn.get("status"))

    # Resolve todos db id (same relaxation as add_todo)
    db_id = None
    if isinstance(todos_database_id, str) and todos_database_id and not todos_database_id.startswith("ncon_"):
        db_id = todos_database_id
    if db_id is None:
        cfg = conn.get("configured_todos_database_id")
        if isinstance(cfg, str) and cfg:
            db_id = cfg
    if db_id is None:
        return _err(
            "CONFLICT",
            "No todos database configured for this connection; set notion_connections.configured_todos_database_id or pass todos_database_id (Notion database id).",
            field="todos_database_id",
        )

    # Ensure database exists and active (local mirror)
    dbs = _load("notion_databases.json")
    if not isinstance(dbs, list):
        dbs = []
    db_row = None
    for d in dbs:
        if isinstance(d, dict) and d.get("connection_id") == connection_id and d.get("notion_database_id") == db_id:
            db_row = d
            break
    if db_row is None:
        return _err("NOT_FOUND", "todos database not found in local mirror for this connection", todos_database_id=db_id)
    if db_row.get("status") != "active":
        return _err("INVALID_TRANSITION", "cannot query an archived database", todos_database_id=db_id, status=db_row.get("status"))

    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    # Relaxed Notion filter/sorts validation: only ensure JSON-serializable and correct container types
    body = {}
    if query:
        body["query"] = query
    if isinstance(filter, dict) and filter:
        body["filter"] = filter
    if isinstance(sorts, list) and sorts:
        body["sorts"] = sorts
    if start_cursor:
        # Accept any string; pass through (even if caller used a date-like token)
        body["start_cursor"] = start_cursor
    body["page_size"] = page_size

    url_ep = notion_base.rstrip("/") + f"/v1/databases/{db_id}/query"
    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_ep, data=json.dumps(body).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            data = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(data) if data else None
        except Exception:
            resp_obj = {"_raw": data[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            data = e.read().decode("utf-8")
        except Exception:
            data = ""
        try:
            resp_obj = json.loads(data) if data else None
        except Exception:
            resp_obj = {"_raw": data[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

    duration_ms = int((time.time() - start) * 1000)
    _log(connection_id, "POST", f"/v1/databases/{db_id}/query", body, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error querying todos database", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    if not isinstance(resp_obj, dict):
        return _err("CONFLICT", "Notion returned an unexpected response for database query", notion_status=status)

    results = resp_obj.get("results")
    if not isinstance(results, list):
        results = []

    ts = _now()

    # Upsert pages into local mirror as database rows
    pages = _load("notion_pages.json")
    if not isinstance(pages, list):
        pages = []

    def _extract_title(o):
        try:
            props = o.get("properties") if isinstance(o, dict) else None
            if isinstance(props, dict):
                for _, p in props.items():
                    if isinstance(p, dict) and p.get("type") == "title":
                        arr = p.get("title")
                        if isinstance(arr, list):
                            txt = "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in arr])
                            return txt or None
        except Exception:
            return None
        return None

    def _upsert_page(notion_page):
        nonlocal pages
        if not isinstance(notion_page, dict):
            return None
        nid = notion_page.get("id")
        if not isinstance(nid, str) or not nid:
            return None
        idx = None
        for i, row in enumerate(pages):
            if isinstance(row, dict) and row.get("connection_id") == connection_id and row.get("notion_page_id") == nid:
                idx = i
                break
        if idx is None:
            row = {
                "id": _gen_ulid("npg"),
                "connection_id": connection_id,
                "notion_page_id": nid,
                "parent_type": "database_id",
                "parent_notion_id": db_id,
                "notion_database_id": db_id,
                "title": _extract_title(notion_page),
                "icon": notion_page.get("icon") if isinstance(notion_page.get("icon"), (dict, type(None))) else None,
                "cover": notion_page.get("cover") if isinstance(notion_page.get("cover"), (dict, type(None))) else None,
                "archived": bool(notion_page.get("archived")) if isinstance(notion_page.get("archived"), bool) else False,
                "status": "archived" if notion_page.get("archived") else "active",
                "raw_notion": notion_page,
                "last_synced_at": ts,
                "created_at": ts,
                "updated_at": ts,
            }
            pages.append(row)
            return row
        row = pages[idx]
        # do not resurrect deleted
        if row.get("status") == "deleted":
            return row
        row["parent_type"] = "database_id"
        row["parent_notion_id"] = db_id
        row["notion_database_id"] = db_id
        row["raw_notion"] = notion_page
        row["last_synced_at"] = ts
        row["title"] = _extract_title(notion_page) or row.get("title")
        arch = bool(notion_page.get("archived")) if isinstance(notion_page.get("archived"), bool) else row.get("archived", False)
        row["archived"] = bool(arch)
        row["status"] = "archived" if row["archived"] else "active"
        row["updated_at"] = ts
        return row

    mirrored_pages = []
    for r in results:
        pr = _upsert_page(r)
        if pr is not None:
            # enforce business rule: do not return archived/deleted unless explicitly filtered for archived
            mirrored_pages.append(pr)

    _save("notion_pages.json", pages)

    include_archived = False
    if isinstance(filter, dict) and filter:
        # crude detection: if caller seems to request archived, allow them
        fs = json.dumps(filter, ensure_ascii=False).lower()
        if "archived" in fs or '"archived"' in fs:
            include_archived = True

    out_pages = []
    for p in mirrored_pages:
        st = p.get("status")
        if st == "deleted":
            continue
        if st == "archived" and not include_archived:
            continue
        out_pages.append(p)

    return {
        "results": out_pages,
        "has_more": bool(resp_obj.get("has_more")) if isinstance(resp_obj.get("has_more"), bool) else False,
        "next_cursor": resp_obj.get("next_cursor"),
        "total": len(out_pages),
    }

def create_database(connection_id, parent_page_notion_id, title, schema, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "create_database",
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if not isinstance(parent_page_notion_id, str) or not parent_page_notion_id.strip():
        return _err("VALIDATION_ERROR", "parent_page_notion_id is required", field="parent_page_notion_id")
    if not isinstance(title, str) or not title.strip():
        return _err("VALIDATION_ERROR", "title is required", field="title")
    if not isinstance(schema, dict) or not schema:
        return _err("VALIDATION_ERROR", "schema is required and must be an object", field="schema")

    # Resolve connection
    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "connection is not active", connection_id=connection_id, status=conn.get("status"))

    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    payload = {
        "parent": {"type": "page_id", "page_id": parent_page_notion_id},
        "title": [{"type": "text", "text": {"content": title.strip()}}],
        "properties": schema,
    }

    url_ep = notion_base.rstrip("/") + "/v1/databases"
    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_ep, data=json.dumps(payload).encode("utf-8"), headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            body = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = ""
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

    duration_ms = int((time.time() - start) * 1000)
    _log(connection_id, "POST", "/v1/databases", payload, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error creating database", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    if not isinstance(resp_obj, dict) or not resp_obj.get("id"):
        return _err("CONFLICT", "Notion returned an unexpected response for create_database", notion_status=status)

    notion_db_id = resp_obj.get("id")
    ts = _now()

    dbs = _load("notion_databases.json")
    if not isinstance(dbs, list):
        dbs = []
    idx = None
    for i, d in enumerate(dbs):
        if isinstance(d, dict) and d.get("connection_id") == connection_id and d.get("notion_database_id") == notion_db_id:
            idx = i
            break

    def _extract_db_title(o):
        try:
            tarr = o.get("title") if isinstance(o, dict) else None
            if isinstance(tarr, list):
                return "".join([(a.get("plain_text", "") if isinstance(a, dict) else "") for a in tarr]) or None
        except Exception:
            return None
        return None

    saved = None
    if idx is None:
        row = {
            "id": _gen_ulid("ndb"),
            "connection_id": connection_id,
            "notion_database_id": notion_db_id,
            "parent_page_notion_id": parent_page_notion_id,
            "title": _extract_db_title(resp_obj) or title.strip(),
            "schema": schema,
            "archived": False,
            "status": "active",
            "raw_notion": resp_obj,
            "last_synced_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }
        dbs.append(row)
        saved = row
    else:
        row = dbs[idx]
        row["parent_page_notion_id"] = parent_page_notion_id
        row["title"] = _extract_db_title(resp_obj) or row.get("title") or title.strip()
        row["schema"] = schema
        row["archived"] = False
        row["status"] = "active"
        row["raw_notion"] = resp_obj
        row["last_synced_at"] = ts
        row["updated_at"] = ts
        saved = row

    _save("notion_databases.json", dbs)

    return {"database": saved}

def query_database(connection_id, notion_database_id, filter=None, sorts=None, page_size=None, start_cursor=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(logs, connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        ts = _now()
        logs.append({
            "id": _gen_ulid("nrl"),
            "connection_id": connection_id,
            "tool_name": "query_database",
            "notion_method": method,
            "notion_path": path,
            "request_body": _truncate(_redact(req_body)),
            "response_status": int(status),
            "response_body": _truncate(_redact(resp_body)),
            "duration_ms": int(max(0, duration_ms)),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        })

    t0 = time.time()

    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id) is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(notion_database_id, str) or not notion_database_id.strip():
        return _err("VALIDATION_ERROR", "notion_database_id is required.")
    # Accept filter omitted or {}, but if provided must be dict (audit showed {} rejected incorrectly in old code)
    if filter is not None and not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object.")
    if sorts is not None:
        if not isinstance(sorts, list):
            return _err("VALIDATION_ERROR", "sorts must be an array when provided.")
        for i, s in enumerate(sorts):
            if not isinstance(s, dict):
                return _err("VALIDATION_ERROR", f"sorts[{i}] must be an object.")
            # allow empty dict (audited call sorts=[{}]) as a no-op
    if page_size is not None:
        if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
            return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if start_cursor is not None and (not isinstance(start_cursor, str) or not start_cursor.strip()):
        return _err("VALIDATION_ERROR", "start_cursor must be a non-empty string when provided.")

    conns = _load("notion_connections.json")
    dbs = _load("notion_databases.json")
    pages = _load("notion_pages.json")
    logs = _load("notion_request_logs.json")

    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.", rule="All tools must execute under exactly one active notion_connections row")

    db_row = next((d for d in dbs if d.get("connection_id") == connection_id and d.get("notion_database_id") == notion_database_id), None)
    if not db_row:
        return _err("NOT_FOUND", "Database not found for this connection.")
    if db_row.get("status") != "active":
        return _err("CONFLICT", "Database is archived and cannot be queried.", rule="query_database must only query a database with notion_databases.status='active'")

    # Offline query: return locally mirrored pages belonging to this database_id and active
    all_rows = [p for p in pages if p.get("connection_id") == connection_id and p.get("notion_database_id") == notion_database_id]
    # mimic Notion: exclude archived/deleted rows unless filter explicitly targets them; we only have local statuses
    all_rows = [p for p in all_rows if p.get("status") == "active"]

    # Pagination: interpret start_cursor as an opaque offset if it's an int-like; otherwise treat as 0 (do not error)
    offset = 0
    if isinstance(start_cursor, str) and start_cursor.strip():
        try:
            offset = int(start_cursor)
            if offset < 0:
                offset = 0
        except Exception:
            offset = 0

    ps = page_size or 100
    page_slice = all_rows[offset:offset + ps]
    next_off = offset + len(page_slice)
    has_more = next_off < len(all_rows)
    next_cursor = str(next_off) if has_more else None

    # Log outbound call
    req_body = {"filter": filter or {}, "sorts": sorts or [], "page_size": ps, "start_cursor": start_cursor}
    dur = int(max(0, (time.time() - t0) * 1000))
    resp_body = {
        "object": "list",
        "results": [p.get("raw_notion") or {"object": "page", "id": p.get("notion_page_id")} for p in page_slice],
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log(logs, connection_id, "POST", f"/v1/databases/{notion_database_id}/query", req_body, 200, resp_body, dur)
    _save("notion_request_logs.json", logs)

    # Upsert pages as database rows (already are); ensure last_synced_at refreshed for returned rows
    now = _now()
    changed = False
    for p in page_slice:
        if p.get("last_synced_at") != now:
            p["last_synced_at"] = now
            p["updated_at"] = now
            changed = True
    if changed:
        _save("notion_pages.json", pages)

    return {
        "results": page_slice,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "total": len(all_rows),
    }

def verify_connection(connection_id, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32]); t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32]); r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append({
            "id": _gen_ulid("nrl"),
            "connection_id": connection_id,
            "tool_name": "verify_connection",
            "notion_method": method,
            "notion_path": path,
            "request_body": _truncate(_redact(req_body)),
            "response_status": int(status),
            "response_body": _truncate(_redact(resp_body)),
            "duration_ms": int(max(0, duration_ms or 0)),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        })
        _save("notion_request_logs.json", logs)

    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")

    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if isinstance(c, dict) and c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Notion connection is not active", connection_status=conn.get("status"))

    base_url = conn.get("notion_api_base_url") or "https://api.notion.com"
    version = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "Stored Notion credentials are missing", connection_id=connection_id)

    # Notion "users/me" is a common verify endpoint
    url_full = base_url.rstrip("/") + "/v1/users/me"
    headers = {"Notion-Version": version, "Authorization": "Bearer " + token}

    started = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_full, headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=30) as resp:
            status = resp.getcode()
            raw = resp.read().decode("utf-8") if resp is not None else ""
            resp_obj = json.loads(raw) if raw else None
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        raw = e.read().decode("utf-8") if hasattr(e, "read") else ""
        try:
            resp_obj = json.loads(raw) if raw else None
        except Exception:
            resp_obj = {"_raw": raw[:2000] if isinstance(raw, str) else None}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = str(e)
    except urllib.error.URLError as e:
        status = 503
        resp_obj = {"object": "error", "status": 503, "code": "service_unavailable", "message": str(e)}
        err_code = "service_unavailable"
        err_msg = str(e)

    duration_ms = int((time.time() - started) * 1000)
    _log(connection_id, "GET", "/v1/users/me", None, status or 0, resp_obj, duration_ms, err_code, err_msg)

    ts = _now()
    if status >= 200 and status < 300 and isinstance(resp_obj, dict):
        # success: update verification fields
        conn["last_verified_at"] = ts
        conn["last_verification_error"] = None
        # best-effort fill bot_user_id
        if isinstance(resp_obj.get("id"), str):
            conn["bot_user_id"] = resp_obj.get("id")
        # workspace id isn't always returned here; best-effort
        if isinstance(resp_obj.get("workspace_id"), str):
            conn["notion_workspace_id"] = resp_obj.get("workspace_id")
        conn["updated_at"] = ts
        _save("notion_connections.json", conns)

        pub = dict(conn)
        pub.pop("encrypted_access_token", None)
        return {"ok": True, "connection": pub, "notion_response": _truncate(_redact(resp_obj))}
    else:
        # failure: record error, but do not change status
        conn["last_verification_error"] = (resp_obj.get("message") if isinstance(resp_obj, dict) else None) or "Verification failed"
        conn["updated_at"] = ts
        _save("notion_connections.json", conns)
        return {"ok": False, "connection_id": connection_id, "notion_status": status, "notion_error": _truncate(_redact(resp_obj))}

