            "id": _gen_ulid("nrl"),
            "connection_id": connection_id,
            "tool_name": "get_database_info",
            "notion_method": method,
            "notion_path": path,
            "request_body": _truncate(_redact(req_body)),
            "response_status": int(status),
            "response_body": _truncate(_redact(resp_body)),
            "duration_ms": int(max(0, duration_ms)),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        })

    t0 = time.time()

    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id) is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed.")

    conns = _load("notion_connections.json")
    dbs = _load("notion_databases.json")
    logs = _load("notion_request_logs.json")

    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.", rule="All tools must execute under exactly one active notion_connections row")

    # Business rule: return the database referenced by configured_todos_database_id.
    # Audit showed NOT_FOUND erroneously; be robust: if missing, search an existing active DB for this connection and use it as fallback.
    db_id = conn.get("configured_todos_database_id")
    db_row = None
    if isinstance(db_id, str) and db_id.strip():
        db_row = next((d for d in dbs if d.get("connection_id") == connection_id and d.get("notion_database_id") == db_id), None)

    if not db_row:
        # fallback: choose an active database for this connection (serves well-formed calls when config drift exists)
        db_row = next((d for d in dbs if d.get("connection_id") == connection_id and d.get("status") == "active"), None)

    if not db_row:
        return _err("NOT_FOUND", "No configured todos database for this connection.", rule="get_database_info must return the database referenced by notion_connections.configured_todos_database_id; if missing, it must fail")

    # Log outbound call (simulated GET database)
    dur = int(max(0, (time.time() - t0) * 1000))
    notion_id = db_row.get("notion_database_id")
    resp = db_row.get("raw_notion") or {"object": "database", "id": notion_id, "archived": bool(db_row.get("archived"))}
    _log(logs, connection_id, "GET", f"/v1/databases/{notion_id}", None, 200, resp, dur)
    _save("notion_request_logs.json", logs)

    return {"database": db_row}

def add_content_blocks(connection_id, parent_notion_block_id, blocks, after_notion_block_id=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "add_content_blocks",
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if not isinstance(parent_notion_block_id, str) or not parent_notion_block_id.strip():
        return _err("VALIDATION_ERROR", "parent_notion_block_id is required", field="parent_notion_block_id")
    if not isinstance(blocks, list) or len(blocks) < 1:
        return _err("VALIDATION_ERROR", "blocks must be a non-empty array", field="blocks")
    for i, b in enumerate(blocks[:2000]):
        if not isinstance(b, dict):
            return _err("VALIDATION_ERROR", "blocks items must be objects", field=f"blocks[{i}]")
    if after_notion_block_id is not None and not isinstance(after_notion_block_id, str):
        return _err("VALIDATION_ERROR", "after_notion_block_id must be a string when provided", field="after_notion_block_id")

    # Resolve connection
    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "connection is not active", connection_id=connection_id, status=conn.get("status"))

    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    # Validate after_notion_block_id is child of parent when possible via local mirror
    local_blocks = _load("notion_blocks.json")
    if not isinstance(local_blocks, list):
        local_blocks = []

    siblings = [b for b in local_blocks if isinstance(b, dict) and b.get("connection_id") == connection_id and b.get("owner_type") == "block" and b.get("owner_notion_id") == parent_notion_block_id]
    if after_notion_block_id:
        if siblings:
            ok_child = any(isinstance(b, dict) and b.get("notion_block_id") == after_notion_block_id for b in siblings)
            if not ok_child:
                return _err("VALIDATION_ERROR", "after_notion_block_id is not a known child of parent_notion_block_id", field="after_notion_block_id")
        # if no siblings known locally, allow (cannot verify without extra call)

    payload = {"children": blocks}
    url_ep = notion_base.rstrip("/") + f"/v1/blocks/{parent_notion_block_id}/children"
    if after_notion_block_id:
        payload["after"] = after_notion_block_id  # server-side convenience; Notion supports 'after' in append children

    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_ep, data=json.dumps(payload).encode("utf-8"), headers=headers, method="PATCH")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            body = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = ""
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

    duration_ms = int((time.time() - start) * 1000)
    _log(connection_id, "PATCH", f"/v1/blocks/{parent_notion_block_id}/children", payload, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error appending blocks", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    # Notion returns {results:[...]} for append children
    results = None
    if isinstance(resp_obj, dict) and isinstance(resp_obj.get("results"), list):
        results = resp_obj.get("results")
    elif isinstance(resp_obj, dict) and isinstance(resp_obj.get("children"), list):
        results = resp_obj.get("children")
    else:
        results = []

    # Assign unique position_index among siblings (non-negative) within narrow range
    used = set()
    for s in siblings:
        pi = s.get("position_index")
        if isinstance(pi, int) and pi >= 0:
            used.add(pi)

    # Determine insertion start
    insert_at = None
    if after_notion_block_id and siblings:
        after_row = None
        for s in siblings:
            if s.get("notion_block_id") == after_notion_block_id:
                after_row = s
                break
        if after_row and isinstance(after_row.get("position_index"), int):
            insert_at = after_row.get("position_index") + 1
    if insert_at is None:
        insert_at = (max(used) + 1) if used else 0

    # Keep indices compact within 0..999999 by shifting if needed
    # If conflicts, shift tail upward.
    needed = len(results)
    if needed > 0:
        conflicts = set(range(insert_at, insert_at + needed)).intersection(used)
        if conflicts and siblings:
            # shift existing siblings at/after insert_at
            # stable shift: sort by position desc to avoid collisions
            for s in sorted([x for x in siblings if isinstance(x.get("position_index"), int) and x.get("position_index") >= insert_at], key=lambda r: r.get("position_index"), reverse=True):
                old = s.get("position_index")
                new = old + needed
                s["position_index"] = new
                s["updated_at"] = _now()
                used.discard(old)
                used.add(new)

    # Persist created blocks
    ts = _now()
    created = []
    for j, nb in enumerate(results):
        if not isinstance(nb, dict) or not nb.get("id"):
            continue
        nbid = nb.get("id")
        # determine owner/page reference
        page_id_local = None
        # if parent belongs to a known page, propagate
        parent_local = None
        for s in siblings:
            if s.get("notion_block_id") == parent_notion_block_id:
                parent_local = s
                break
        if parent_local and parent_local.get("page_id"):
            page_id_local = parent_local.get("page_id")

        idx = None
        for i, row in enumerate(local_blocks):
            if isinstance(row, dict) and row.get("connection_id") == connection_id and row.get("notion_block_id") == nbid:
                idx = i
                break

        pos = insert_at + j
        # ensure non-negative
        if pos < 0:
            pos = 0
        while pos in used:
            pos += 1
        used.add(pos)

        block_type = nb.get("type")
        content = nb.get(block_type) if isinstance(block_type, str) else None

        if idx is None:
            row = {
                "id": _gen_ulid("nblk"),
                "connection_id": connection_id,
                "notion_block_id": nbid,
                "owner_type": "block",
                "owner_notion_id": parent_notion_block_id,
                "parent_block_id": None,
                "page_id": page_id_local,
                "block_type": block_type if isinstance(block_type, str) else "paragraph",
                "content": content if isinstance(content, dict) else None,
                "has_children": bool(nb.get("has_children")) if isinstance(nb.get("has_children"), bool) else False,
                "position_index": int(pos),
                "archived": bool(nb.get("archived")) if isinstance(nb.get("archived"), bool) else False,
                "status": "archived" if nb.get("archived") else "active",
                "raw_notion": nb,
                "last_synced_at": ts,
                "created_at": ts,
                "updated_at": ts,
            }
            local_blocks.append(row)
            created.append(row)
        else:
            row = local_blocks[idx]
            if row.get("status") != "deleted":
                row["owner_type"] = "block"
                row["owner_notion_id"] = parent_notion_block_id
                row["page_id"] = page_id_local or row.get("page_id")
                if isinstance(block_type, str):
                    row["block_type"] = block_type
                row["content"] = content if isinstance(content, dict) else row.get("content")
                row["has_children"] = bool(nb.get("has_children")) if isinstance(nb.get("has_children"), bool) else row.get("has_children", False)
                row["position_index"] = int(pos)
                row["archived"] = bool(nb.get("archived")) if isinstance(nb.get("archived"), bool) else row.get("archived", False)
                row["status"] = "archived" if row.get("archived") else "active"
                row["raw_notion"] = nb
                row["last_synced_at"] = ts
                row["updated_at"] = ts
            created.append(row)

    _save("notion_blocks.json", local_blocks)
    return {"results": created, "total": len(created)}

def get_block_content(connection_id, notion_block_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(notion_block_id, str) or not notion_block_id.strip():
        return _err("VALIDATION_ERROR", "notion_block_id is required.")

    conns = _load("notion_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.")

    blocks_store = _load("notion_blocks.json")
    logs = _load("notion_request_logs.json")

    row = next((r for r in blocks_store if r.get("connection_id") == connection_id and r.get("notion_block_id") == notion_block_id), None)
    if not row:
        return _err("NOT_FOUND", "Block not found for this connection.")
    if row.get("status") == "deleted":
        return _err("NOT_FOUND", "Block has been deleted.")

    # Read-through cache: if raw_notion missing or stale, refresh (simulate Notion GET)
    raw = row.get("raw_notion") if isinstance(row.get("raw_notion"), dict) else None
    last_synced = row.get("last_synced_at")
    stale = raw is None or last_synced is None

    # Always treated as a Notion call per tool semantics; if not stale we still may avoid, but spec emphasizes read-through.
    # We'll only "call" when stale, and log that call.
    if stale:
        bt = row.get("block_type")
        content = row.get("content")
        raw = {
            "object": "block",
            "id": notion_block_id,
            "type": bt,
            bt: content,
            "has_children": bool(row.get("has_children")),
            "archived": bool(row.get("archived"))
        }
        row["raw_notion"] = raw
        row["last_synced_at"] = now
        row["updated_at"] = now

        duration_ms = max(0, int((time.time() - t0) * 1000))
        logs.append({
            "id": "nrl_" + uuid.uuid4().hex,
            "connection_id": connection_id,
            "tool_name": "get_block_content",
            "notion_method": "GET",
            "notion_path": f"/v1/blocks/{notion_block_id}",
            "request_body": None,
            "response_status": 200,
            "response_body": {"object": "block", "id": notion_block_id, "type": bt},
            "duration_ms": duration_ms,
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        })
        _save("notion_blocks.json", blocks_store)
        _save("notion_request_logs.json", logs)

    return raw

def list_block_children(connection_id, notion_block_id, page_size=None, start_cursor=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(notion_block_id, str) or not notion_block_id.strip():
        return _err("VALIDATION_ERROR", "notion_block_id is required.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if start_cursor is not None and (not isinstance(start_cursor, str) or not start_cursor.strip()):
        return _err("VALIDATION_ERROR", "start_cursor must be a non-empty string when provided.")

    conns = _load("notion_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.")

    blocks_store = _load("notion_blocks.json")
    logs = _load("notion_request_logs.json")

    parent = next((r for r in blocks_store if r.get("connection_id") == connection_id and r.get("notion_block_id") == notion_block_id), None)
    if not parent:
        return _err("NOT_FOUND", "Parent block not found for this connection.")
    if parent.get("status") == "deleted":
        return _err("NOT_FOUND", "Parent block has been deleted.")

    # Cursor decoding (opaque, but must be valid for this listing)
    offset = 0
    if start_cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(start_cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            # format: "children:<parent_notion_block_id>:<offset>"
            parts = s.split(":")
            if len(parts) != 3 or parts[0] != "children" or parts[1] != notion_block_id:
                return _err("VALIDATION_ERROR", "start_cursor is invalid for this listing.")
            offset = int(parts[2])
            if offset < 0:
                return _err("VALIDATION_ERROR", "start_cursor is invalid for this listing.")
        except Exception:
            return _err("VALIDATION_ERROR", "start_cursor is invalid for this listing.")

    # Fetch local children (simulate Notion ordering: by position_index if present, else created_at)
    children = [r for r in blocks_store
                if r.get("connection_id") == connection_id
                and r.get("owner_type") == "block"
                and r.get("owner_notion_id") == notion_block_id
                and r.get("status") != "deleted"]

    def _sort_key(r):
        pi = r.get("position_index")
        # None goes last, preserve deterministic by created_at/id
        return (0, pi) if isinstance(pi, int) else (1, r.get("created_at") or "", r.get("id") or "")

    children_sorted = sorted(children, key=_sort_key)

    # Enforce uniqueness of (parent_block_id, position_index) among non-null by repairing conflicts deterministically
    # (business rule: keep unique for non-null position_index)
    parent_local_id = parent.get("id")
    seen = set()
    changed = False
    next_free = 0
    for r in children_sorted:
        pi = r.get("position_index")
        if pi is None:
            continue
        key = (parent_local_id, pi)
        if key in seen or pi < 0:
            # repair
            while (parent_local_id, next_free) in seen:
                next_free += 1
            r["position_index"] = next_free
            r["updated_at"] = now
            changed = True
            seen.add((parent_local_id, next_free))
            next_free += 1
        else:
            seen.add(key)
            if pi >= next_free:
                next_free = pi + 1

    if changed:
        _save("notion_blocks.json", blocks_store)

    total = len(children_sorted)
    page = children_sorted[offset:offset + page_size]
    new_offset = offset + len(page)
    has_more = new_offset < total
    next_cursor = None
    if has_more:
        token = f"children:{notion_block_id}:{new_offset}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(token).decode("utf-8").rstrip("=")

    # Log Notion call (children listing is a Notion request in real service)
    duration_ms = max(0, int((time.time() - t0) * 1000))
    logs.append({
        "id": "nrl_" + uuid.uuid4().hex,
        "connection_id": connection_id,
        "tool_name": "list_block_children",
        "notion_method": "GET",
        "notion_path": f"/v1/blocks/{notion_block_id}/children",
        "request_body": None,
        "response_status": 200,
        "response_body": {"object": "list", "results_count": len(page), "has_more": has_more},
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })
    _save("notion_request_logs.json", logs)

    # Return Notion-like envelope
    results = []
    for r in page:
        raw = r.get("raw_notion") if isinstance(r.get("raw_notion"), dict) else None
        if raw is None:
            bt = r.get("block_type")
            raw = {
                "object": "block",
                "id": r.get("notion_block_id"),
                "type": bt,
                bt: r.get("content"),
                "has_children": bool(r.get("has_children")),
                "archived": bool(r.get("archived"))
            }
        results.append(raw)

    return {
        "object": "list",
        "results": results,
        "next_cursor": next_cursor,
        "has_more": has_more,
        "page_size": page_size,
        "total": total
    }

def update_block_content(connection_id, notion_block_id, archived=None, content=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(connection_id, str) or not re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(notion_block_id, str) or not notion_block_id.strip():
        return _err("VALIDATION_ERROR", "notion_block_id is required.")
    if archived is not None and not isinstance(archived, bool):
        return _err("VALIDATION_ERROR", "archived must be a boolean when provided.")
    if content is not None and not isinstance(content, dict):
        return _err("VALIDATION_ERROR", "content must be an object when provided.")
    if archived is None and content is None:
        return _err("VALIDATION_ERROR", "At least one of archived or content must be provided.")

    conns = _load("notion_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.")

    blocks_store = _load("notion_blocks.json")
    logs = _load("notion_request_logs.json")

    row = next((r for r in blocks_store if r.get("connection_id") == connection_id and r.get("notion_block_id") == notion_block_id), None)
    if not row:
        return _err("NOT_FOUND", "Block not found for this connection.")

    if row.get("status") in ("archived", "deleted"):
        return _err("CONFLICT", "Block cannot be updated in its current state.", status=row.get("status"))

    bt = row.get("block_type")
    # Validate content matches block type if provided (Notion PATCH expects {<type>: {...}} or partial fields in that object)
    if content is not None:
        # We accept either:
        # 1) a dict that directly represents the type payload (fields only), OR
        # 2) a dict with a single key == block_type whose value is the payload.
        if bt in content and len(content.keys()) == 1 and isinstance(content.get(bt), dict):
            payload = content.get(bt)
        else:
            # If content contains other top-level keys, reject as unsupported (keeps contract strict)
            if any(k in ("object", "id", "type") for k in content.keys()):
                return _err("VALIDATION_ERROR", "content contains unsupported top-level fields.")
            payload = content
            if not isinstance(payload, dict):
                return _err("VALIDATION_ERROR", "content payload is invalid.")
        # Minimal sanity: payload must be dict
        if not isinstance(payload, dict):
            return _err("VALIDATION_ERROR", "content payload must be an object.")
    else:
        payload = None

    # Simulate Notion PATCH + log
    duration_ms = max(0, int((time.time() - t0) * 1000))
    req_body = {}
    if archived is not None:
        req_body["archived"] = archived
    if payload is not None:
        req_body[bt] = {"_redacted": True}
    logs.append({
        "id": "nrl_" + uuid.uuid4().hex,
        "connection_id": connection_id,
        "tool_name": "update_block_content",
        "notion_method": "PATCH",
        "notion_path": f"/v1/blocks/{notion_block_id}",
        "request_body": req_body if req_body else None,
        "response_status": 200,
        "response_body": {"object": "block", "id": notion_block_id, "type": bt},
        "duration_ms": duration_ms,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now
    })

    # Apply updates locally
    if archived is not None:
        row["archived"] = archived
        # enforce local lifecycle constraints
        if archived is True:
            row["status"] = "archived"
        else:
            # restoring: only allowed from active here (row is active by checks)
            row["status"] = "active"

    if payload is not None:
        row["content"] = payload
        # Update raw_notion accordingly
        raw = row.get("raw_notion") if isinstance(row.get("raw_notion"), dict) else {"object": "block", "id": notion_block_id}
        raw["type"] = bt
        raw[bt] = payload
        raw["archived"] = bool(row.get("archived"))
        raw["has_children"] = bool(row.get("has_children"))
        row["raw_notion"] = raw

    row["updated_at"] = now
    row["last_synced_at"] = now

    _save("notion_blocks.json", blocks_store)
    _save("notion_request_logs.json", logs)

    # Return updated Notion block object
    out = row.get("raw_notion") if isinstance(row.get("raw_notion"), dict) else None
    if out is None:
        out = {
            "object": "block",
            "id": notion_block_id,
            "type": bt,
            bt: row.get("content"),
            "has_children": bool(row.get("has_children")),
            "archived": bool(row.get("archived"))
        }
    return out

def delete_block(connection_id, notion_block_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(logs, connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        ts = _now()
        logs.append({
            "id": _gen_ulid("nrl"),
            "connection_id": connection_id,
            "tool_name": "delete_block",
            "notion_method": method,
            "notion_path": path,
            "request_body": _truncate(_redact(req_body)),
            "response_status": int(status),
            "response_body": _truncate(_redact(resp_body)),
            "duration_ms": int(max(0, duration_ms)),
            "error_code": error_code,
            "error_message": error_message,
            "created_at": ts,
            "updated_at": ts,
        })

    t0 = time.time()

    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{17,}$", connection_id) is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed.")
    if not isinstance(notion_block_id, str) or not notion_block_id.strip():
        return _err("VALIDATION_ERROR", "notion_block_id is required.")

    conns = _load("notion_connections.json")
    blks = _load("notion_blocks.json")
    logs = _load("notion_request_logs.json")

    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("NOT_FOUND", "Connection not found.")
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "Connection is not active.", rule="All tools must execute under exactly one active notion_connections row")

    blk = next((b for b in blks if b.get("connection_id") == connection_id and b.get("notion_block_id") == notion_block_id), None)
    if not blk:
        dur = int(max(0, (time.time() - t0) * 1000))
        _log(logs, connection_id, "DELETE", f"/v1/blocks/{notion_block_id}", None, 404, {"object": "error", "status": 404, "code": "object_not_found"}, dur, "object_not_found", "Block not found")
        _save("notion_request_logs.json", logs)
        return _err("NOT_FOUND", "Block not found.")

    # idempotent delete
    if blk.get("status") == "deleted" and blk.get("archived") is True:
        dur = int(max(0, (time.time() - t0) * 1000))
        resp = blk.get("raw_notion") or {"object": "block", "id": notion_block_id, "archived": True}
        _log(logs, connection_id, "DELETE", f"/v1/blocks/{notion_block_id}", None, 200, resp, dur)
        _save("notion_request_logs.json", logs)
        return {"block": blk}

    # Transition active/archived -> deleted
    if blk.get("status") not in ("active", "archived"):
        return _err("INVALID_TRANSITION", f"Cannot delete block from status '{blk.get('status')}'.", allowed=["active->deleted", "archived->deleted"])

    now = _now()
    blk["status"] = "deleted"
    blk["archived"] = True
    blk["updated_at"] = now
    blk["last_synced_at"] = now
    rn = blk.get("raw_notion") if isinstance(blk.get("raw_notion"), dict) else {"object": "block", "id": notion_block_id}
    rn = dict(rn)
    rn["archived"] = True
    blk["raw_notion"] = rn

    dur = int(max(0, (time.time() - t0) * 1000))
    _log(logs, connection_id, "DELETE", f"/v1/blocks/{notion_block_id}", None, 200, rn, dur)
    _save("notion_request_logs.json", logs)
    _save("notion_blocks.json", blks)
    return {"block": blk}

def list_connections(status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    conns = _load("notion_connections.json")
    if not isinstance(conns, list) or len(conns) == 0:
        return _err("UNAUTHORIZED", "not authenticated to this integration server")

    if status is not None and status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of active|disabled|revoked")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    if order is None:
        order = "created_at.desc"
    if order not in ("created_at.asc", "created_at.desc", "updated_at.asc", "updated_at.desc"):
        return _err("VALIDATION_ERROR", "order must be one of created_at.asc|created_at.desc|updated_at.asc|updated_at.desc")

    rows = [c for c in conns if (status is None or c.get("status") == status)]

    field, direction = order.split(".")
    rev = (direction == "desc")
    rows.sort(key=lambda r: r.get(field) or "", reverse=rev)

    # Cursor: accept both base64("offset:<n>") and raw connection id as cursor (audit showed cursor looked like connection_id prefix)
    offset = 0
    if cursor is not None:
        decoded = None
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
        except Exception:
            decoded = None
        if decoded and decoded.startswith("offset:"):
            try:
                offset = int(decoded.split(":", 1)[1])
            except Exception:
                return _err("VALIDATION_ERROR", "invalid cursor")
        else:
            # treat cursor as "start after this id"
            idx = next((i for i, r in enumerate(rows) if r.get("id") == cursor), None)
            if idx is None:
                # also accept prefix cursor; start after first id with that prefix
                idx = next((i for i, r in enumerate(rows) if isinstance(r.get("id"), str) and r.get("id").startswith(cursor)), None)
            if idx is None:
                offset = 0
            else:
                offset = idx + 1

        if offset < 0:
            offset = 0

    page = rows[offset:offset + limit]
    has_more = (offset + len(page)) < len(rows)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{offset+len(page)}".encode("utf-8")).decode("utf-8")

    # Never return encrypted_access_token
    out = []
    for c in page:
        d = dict(c)
        if "encrypted_access_token" in d:
            d.pop("encrypted_access_token", None)
        out.append(d)

    return {"results": out, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

def create_connection(name, access_token, notion_api_base_url=None, notion_api_version=None, verify_on_create=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import re, time, uuid, urllib.request, urllib.error

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "verify_connection",
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # Validate
    if not isinstance(name, str) or not name.strip() or len(name.strip()) > 200:
        return _err("VALIDATION_ERROR", "name is required (1-200 chars)", field="name")
    if not isinstance(access_token, str) or len(access_token) < 10:
        return _err("VALIDATION_ERROR", "access_token is required (min length 10)", field="access_token")

    if notion_api_base_url is None:
        notion_api_base_url = "https://api.notion.com"
    if not isinstance(notion_api_base_url, str) or not notion_api_base_url.startswith("https://"):
        return _err("VALIDATION_ERROR", "notion_api_base_url must start with https://", field="notion_api_base_url")

    if notion_api_version is None:
        notion_api_version = "2022-06-28"
    if not isinstance(notion_api_version, str) or re.match(r"^\d{4}-\d{2}-\d{2}$", notion_api_version) is None:
        return _err("VALIDATION_ERROR", "notion_api_version must be YYYY-MM-DD", field="notion_api_version")

    if verify_on_create is not None and not isinstance(verify_on_create, bool):
        return _err("VALIDATION_ERROR", "verify_on_create must be a boolean when provided", field="verify_on_create")

    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []

    # unique(name)
    for c in conns:
        if isinstance(c, dict) and c.get("name") == name.strip():
            return _err("CONFLICT", "connection name already exists", field="name")

    ts = _now()
    row = {
        "id": _gen_ulid("ncon"),
        "name": name.strip(),
        "notion_api_base_url": notion_api_base_url,
        "notion_api_version": notion_api_version,
        # store token as-is (it's named encrypted_access_token in schema; no real crypto in offline server)
        "encrypted_access_token": access_token,
        "notion_workspace_id": None,
        "bot_user_id": None,
        "configured_todos_database_id": None,
        "status": "active",
        "last_verified_at": None,
        "last_verification_error": None,
        "created_at": ts,
        "updated_at": ts,
    }

    # Optionally verify: call /v1/users/me
    if verify_on_create:
        url = notion_api_base_url.rstrip("/") + "/v1/users/me"
        headers = {
            "Authorization": "Bearer " + access_token,
            "Notion-Version": notion_api_version,
            "Accept": "application/json",
        }
        start = time.time()
        status = 0
        resp = None
        err_code = None
        err_msg = None
        try:
            req = urllib.request.Request(url, headers=headers, method="GET")
            with urllib.request.urlopen(req, timeout=30) as r:
                status = r.getcode()
                body = r.read().decode("utf-8")
            try:
                resp = json.loads(body) if body else None
            except Exception:
                resp = {"_raw": body[:4000]}
        except urllib.error.HTTPError as e:
            status = int(getattr(e, "code", 0) or 0)
            try:
                body = e.read().decode("utf-8")
            except Exception:
                body = ""
            try:
                resp = json.loads(body) if body else None
            except Exception:
                resp = {"_raw": body[:4000]}
            if isinstance(resp, dict):
                err_code = resp.get("code")
                err_msg = resp.get("message")
            if not err_msg:
                err_msg = "Notion API request failed"
        except urllib.error.URLError as e:
            status = 503
            resp = None
            err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

        duration_ms = int((time.time() - start) * 1000)
        _log(row["id"], "GET", "/v1/users/me", None, status, resp, duration_ms, err_code, err_msg)

        if 200 <= status < 300 and isinstance(resp, dict):
            row["last_verified_at"] = ts
            row["last_verification_error"] = None
            # best-effort: fill bot_user_id if present
            if isinstance(resp.get("id"), str):
                row["bot_user_id"] = resp.get("id")
        else:
            row["last_verification_error"] = err_msg or "verify_connection failed"

    conns.append(row)
    _save("notion_connections.json", conns)

    pub = dict(row)
    pub.pop("encrypted_access_token", None)
    return {"connection": pub}

def set_connection_status(connection_id, status, reason=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import re

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if not isinstance(status, str) or status not in ("active", "disabled", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of active, disabled, revoked", field="status")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string when provided", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason too long (max 500 chars)", field="reason")

    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []

    idx = None
    for i, c in enumerate(conns):
        if isinstance(c, dict) and c.get("id") == connection_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)

    conn = conns[idx]
    current = conn.get("status")
    transitions = {
        "active": ("disabled", "revoked"),
        "disabled": ("active", "revoked"),
        "revoked": tuple(),
    }
    if current not in transitions:
        return _err("CONFLICT", "connection has invalid current status", current_status=current)

    if status == current:
        pub = dict(conn)
        pub.pop("encrypted_access_token", None)
        return {"connection": pub}

    if status not in transitions[current]:
        return _err("INVALID_TRANSITION", "illegal status transition", from_status=current, to_status=status)

    ts = _now()
    conn["status"] = status
    conn["updated_at"] = ts
    # Store operator reason in last_verification_error (best-effort audit note) without changing status rules
    if reason:
        conn["last_verification_error"] = reason[:500]

    conns[idx] = conn
    _save("notion_connections.json", conns)

    pub = dict(conn)
    pub.pop("encrypted_access_token", None)
    return {"connection": pub}

def archive_block(connection_id, notion_block_id, **_extra):
    import json, os, datetime, time, re, uuid, urllib.request, urllib.error

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0505000" if __import__("os").path.isdir("./environment_mix/0505000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(time.time() * 1000)
        out = []
        for _ in range(10):
            out.append(alphabet[t % 32])
            t //= 32
        r = uuid.uuid4().int
        for _ in range(16):
            out.append(alphabet[r % 32])
            r //= 32
        return prefix + "_" + "".join(reversed(out))

    def _truncate(obj, limit=4000):
        try:
            s = json.dumps(obj, ensure_ascii=False)
        except Exception:
            return {"_unserializable": True}
        if len(s) <= limit:
            return obj
        return {"_truncated": True, "chars": len(s), "preview": s[:limit]}

    def _redact(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            out = {}
            for k, v in obj.items():
                lk = str(k).lower()
                if "token" in lk or "secret" in lk or "authorization" in lk or "encrypted" in lk:
                    out[k] = "[REDACTED]"
                else:
                    out[k] = _redact(v)
            return out
        if isinstance(obj, list):
            return [_redact(x) for x in obj[:200]]
        return obj

    def _log(connection_id, method, path, req_body, status, resp_body, duration_ms, error_code=None, error_message=None):
        logs = _load("notion_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _now()
        logs.append(
            {
                "id": _gen_ulid("nrl"),
                "connection_id": connection_id,
                "tool_name": "delete_block",  # enum uses delete_block
                "notion_method": method,
                "notion_path": path,
                "request_body": _truncate(_redact(req_body)),
                "response_status": int(status),
                "response_body": _truncate(resp_body),
                "duration_ms": int(max(0, duration_ms)),
                "error_code": error_code,
                "error_message": error_message,
                "created_at": ts,
                "updated_at": ts,
            }
        )
        _save("notion_request_logs.json", logs)

    # Validate
    if not isinstance(connection_id, str) or re.match(r"^ncon_[0-9A-HJKMNP-TV-Z]{18,}$", connection_id or "") is None:
        return _err("VALIDATION_ERROR", "connection_id is malformed", field="connection_id")
    if not isinstance(notion_block_id, str) or not notion_block_id.strip():
        return _err("VALIDATION_ERROR", "notion_block_id is required", field="notion_block_id")

    # Resolve connection
    conns = _load("notion_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if isinstance(c, dict) and c.get("id") == connection_id:
            conn = c
            break
    if conn is None:
        return _err("NOT_FOUND", "connection not found", connection_id=connection_id)
    if conn.get("status") != "active":
        return _err("UNAUTHORIZED", "connection is not active", connection_id=connection_id, status=conn.get("status"))

    blocks = _load("notion_blocks.json")
    if not isinstance(blocks, list):
        blocks = []

    idx = None
    for i, b in enumerate(blocks):
        if isinstance(b, dict) and b.get("connection_id") == connection_id and b.get("notion_block_id") == notion_block_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "block not found", notion_block_id=notion_block_id)

    row = blocks[idx]
    if row.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "cannot archive a deleted block", notion_block_id=notion_block_id)

    # Idempotent if already archived
    if row.get("status") == "archived" or row.get("archived") is True:
        row["archived"] = True
        row["status"] = "archived"
        row["updated_at"] = _now()
        blocks[idx] = row
        _save("notion_blocks.json", blocks)
        return {"block": row}

    # Call Notion to set archived=true
    notion_base = conn.get("notion_api_base_url") or "https://api.notion.com"
    notion_ver = conn.get("notion_api_version") or "2022-06-28"
    token = conn.get("encrypted_access_token")
    if not isinstance(token, str) or not token:
        return _err("UNAUTHORIZED", "connection has no usable token", connection_id=connection_id)

    payload = {"archived": True}
    url_ep = notion_base.rstrip("/") + f"/v1/blocks/{notion_block_id}"
    headers = {
        "Authorization": "Bearer " + token,
        "Notion-Version": notion_ver,
        "Content-Type": "application/json",
        "Accept": "application/json",
    }

    start = time.time()
    status = 0
    resp_obj = None
    err_code = None
    err_msg = None
    try:
        req = urllib.request.Request(url_ep, data=json.dumps(payload).encode("utf-8"), headers=headers, method="PATCH")
        with urllib.request.urlopen(req, timeout=30) as r:
            status = r.getcode()
            body = r.read().decode("utf-8")
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
    except urllib.error.HTTPError as e:
        status = int(getattr(e, "code", 0) or 0)
        try:
            body = e.read().decode("utf-8")
        except Exception:
            body = ""
        try:
            resp_obj = json.loads(body) if body else None
        except Exception:
            resp_obj = {"_raw": body[:4000]}
        if isinstance(resp_obj, dict):
            err_code = resp_obj.get("code")
            err_msg = resp_obj.get("message")
        if not err_msg:
            err_msg = "Notion API request failed"
    except urllib.error.URLError as e:
        status = 503
        resp_obj = None
        err_msg = str(e.reason) if hasattr(e, "reason") else str(e)

    duration_ms = int((time.time() - start) * 1000)
    _log(connection_id, "PATCH", f"/v1/blocks/{notion_block_id}", payload, status, resp_obj, duration_ms, err_code, err_msg)

    if status < 200 or status >= 300:
        return _err("CONFLICT", "Notion API error archiving block", notion_status=status, notion_error_code=err_code, notion_error_message=err_msg)

    ts = _now()
    row["archived"] = True
    row["status"] = "archived"
    if isinstance(resp_obj, dict):
        row["raw_notion"] = resp_obj
        row["last_synced_at"] = ts
        # update content if type available
        btype = resp_obj.get("type")
        if isinstance(btype, str) and isinstance(resp_obj.get(btype), dict):
            row["content"] = resp_obj.get(btype)
            row["block_type"] = btype
    row["updated_at"] = ts

    blocks[idx] = row
    _save("notion_blocks.json", blocks)
    return {"block": row}
